def clean(df):
    df = df.dropna(subset=['sex'])
    df['sex'] = df['sex'].str.lower()
    valid_sex = df['sex'].isin(['male', 'female'])
    df = df[valid_sex]
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    return df

